let S, N;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(0, 0, 8);
	describe("slices view on antiprism");

  noFill();
	stroke("silver");
  strokeWeight(2);
	S = max(width, height);
	N = ~~random(3, 9);
  loop();
}

function draw() {
	background("rgb(2, 2, 8)");

	const ptsT = nCirclePts(width/2, height/2, S/8, N)
	const ptsB = nCirclePts(width/2, height/2, S/8, N, false)
	const dx = abs(ptsT[1].x - ptsT[0].x);
	const dy = dx*sqrt(3)/2;

	// stripe	
	stroke("silver");
	const p1 = {x: width/2 - dx/2 - ~~((N-1)/2)*dx, y: height/2 - dy/2}
	const p2 = {x: p1.x + N * dx, y: p1.y}
	// line(p1.x, p1.y, p2.x, p2.y);
	const p3 = {x: p1.x + 0.5*dx*(N%2==0 ? -1 : 1), y: height/2 + dy/2}
	const p4 = {x: p3.x + N * dx, y: p3.y}
	// line(p3.x, p3.y, p4.x, p4.y);
	drawTriaStripes(p1, p2, p3, p4)

	// n-shapes
	stroke("cyan");
	drawShape(width/2 - dx/2, height/2 - dy/2 - 1, ptsB);
	stroke("purple");
	drawShape(width/2, height/2 + dy/2 + 1, ptsT);

  // noLoop() removed for animation
}

function drawTriaStripes(p1, p2, p3, p4) {
	var dx = (p2.x-p1.x)/N;
	var dy = p3.y-p1.y;
	const y = p1.y;
	for (let i = 0; i < N; i++) {
		// top
		stroke(lerpColor(color("cyan"), color("purple"), i/N));
		let x = map(i, 0, N, p1.x, p2.x);
		triangle(x, y, x+dx-1, y, x+dx/2, y+dy-1)
		// bottom
		stroke(lerpColor(color("purple"), color("cyan"), i/N));
		x = map(i, 0, N, p3.x, p4.x);
		triangle(x, y+dy, x+dx-1, y+dy, x+dx/2, y+1)
	}
}

function drawShape(x, y, pts) {
	beginShape();
	for (let f = 1; f > 0; f -= 0.05)
	for (let p of pts) {
		vertex(x + p.x * f, y + p.y * f);
	}
	endShape(CLOSE);
}

function nCirclePts(x, y, r, n, tl = true) {
	const da = TWO_PI / n;
	const sa = tl ? (TWO_PI - da/2 - HALF_PI) : (TWO_PI + da/2 + HALF_PI)

	let pts = []
	for (let a = 0; a < TWO_PI - da/2; a += da) {
		const xx = cos(a + sa) * r;
		const yy = sin(a + sa) * r;
		pts.push({x: xx, y: yy});
	}

	// adjust offset to be 1st pt at {0;0}
	const ox = pts[0].x;
	const oy = pts[0].y;
	for (let p of pts) {
		p.x -= ox;
		p.y -= oy;
	}

	return pts;
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
